const ProstheticsText = {
  cards: {
    free: {
      eng: `Free prosthetics for those who lost their limbs as a result of the war. `,
    },
    psychological: {
      eng: `Psychological support and emotional recovery of victims.`,
    },
    unite: {
      eng: `Unite as many people as possible to help victims of war. .`,
    },
  },
  titleText: {
    prosthetics: {
      eng: "prosthetics",
    },
    for: {
      eng: "for",
    },
    ukrainians: {
      eng: "Ukrainians",
    },
  },
  paragraph: {
    top: {
      eng: `Our current project is Prosthetics for Ukrainians.
      `,
    },
    bottom: {
      eng: `The goal of the project is to help Ukrainian children, soldiers and civilians who have lost their limbs during the war to get free quality prosthetics in the USA.`,
    },
  },
};

const iconsArr = [iconIntegra, iconHeart, iconPeople];
const Prosthetics = () => {
  const { lang } = useContext(LanguageContext);
  const { height } = useContext(ScreenModeAndSizeContext);
  const { mobile } = useContext(ScreenModeAndSizeContext);
  const mobileDesktopClass = () => {
    if (mobile) return "mobile";
    return "desktop";
  };

  const Cards = Object.keys(ProstheticsText.cards).map((key, i) => {
    return (
      <Card
        key={i}
        icon={iconsArr[i]}
        text={ProstheticsText.cards[key][lang]}
        reverse
      />
    );
  });

  return (
    <section style={{ height: height }} className={`${styles.section} section`}>
      <div className={styles.block}>
        <div className={`${styles.textTitle} uppercase`}>
          <h1>
            <span className={`${styles.flag}`}></span>
            {ProstheticsText.titleText.prosthetics[lang]}
          </h1>
          <h2>
            <span className={` ${styles.toLowerCaseItalic}`}>
              {ProstheticsText.titleText.for[lang]}
            </span>
            {ProstheticsText.titleText.ukrainians[lang]}
          </h2>
        </div>
        <div className={`${styles.text} h2 ${mobileDesktopClass()}`}>
          <h2>{ProstheticsText.paragraph.top[lang]}</h2>
          <br />
          <h2>{ProstheticsText.paragraph.bottom[lang]}</h2>
        </div>
        <div className={`${styles.cards} `}>{Cards}</div>
      </div>
      <Image
        src="/img-ukraine.png"
        object-fit="contain"
        // priority
        alt="Picture of the author"
        width={2560}
        height={1440}
        className={styles.ukrainianMap}
      />
    </section>
  );
};

export default Prosthetics;
